#!/usr/bin/env bash
# crossplane-stable/crossplane 2.3.1 - base variant: default
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/crossplane-stable-crossplane-2-3-1.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install it with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# The installer subcommand is a plugin and is not in the public cub build
# yet. Stop here, before this script touches any cluster.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer command is a plugin that ships separately from the cub CLI and is not yet publicly available. The standard cub install script does not include it.\nThis cub build does not have it, so this script stops now, before any cluster work.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the default base variant into ./crossplane-stable-crossplane-2-3-1-default"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/crossplane-stable-crossplane:2.3.1 --base default --work-dir ./crossplane-stable-crossplane-2-3-1-default --non-interactive --namespace default

say "Read what was rendered; nothing has touched the cluster yet"
ls ./crossplane-stable-crossplane-2-3-1-default/out/manifests

say "Ensure the default namespace exists"
kubectl create namespace default --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./crossplane-stable-crossplane-2-3-1-default/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./crossplane-stable-crossplane-2-3-1-default/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./crossplane-stable-crossplane-2-3-1-default/out/manifests

say "Done. The cluster received exactly the files in ./crossplane-stable-crossplane-2-3-1-default/out."
